module tb_cci;
  logic clk=0; logic reset_n=0;
  logic [4:0] done;
  always #5 clk=~clk;
  initial begin #20; reset_n=1; end
  cci_case_32 case_32(clk,reset_n,done[0]);
  cci_case_64 case_64(clk,reset_n,done[1]);
  cci_case_128 case_128(clk,reset_n,done[2]);
  cci_case_256 case_256(clk,reset_n,done[3]);
  cci_case_512 case_512(clk,reset_n,done[4]);
  initial begin wait (&done); $display("HWIF_SMOKE_PASS cci"); $finish; end
  initial begin #100000; $fatal(1,"timeout"); end
endmodule
